// Debug-only demo workspace (fictional data, no Supabase).
#if DEBUG
import Foundation

/// Decoded `demo-fixture-manifest.json` (generated by Tools/DemoFixtures).
///
/// Ids are deterministic UUID strings; activity dates are day offsets relative to the seed
/// day so the demo always looks current; drawing / document dates are fixed ISO days.
struct DemoManifest: Decodable {
    var formatVersion: Int
    var seedVersion: String
    var demoUserId: String
    var contractors: [Contractor]
    var disciplines: [Discipline]
    var companies: [Company]
    var people: [Person]
    var equipment: [Equipment]
    var projects: [Project]

    struct Contractor: Decodable { var id: String; var name: String; var notes: String? }
    struct Discipline: Decodable { var id: String; var name: String }

    struct Company: Decodable {
        var id: String
        var name: String
        var trade: String?
        var taxId: String?
        var phone: String?
        var email: String?
        var website: String?
        var address: String?
        var notes: String?
    }

    struct Person: Decodable {
        var id: String
        var firstName: String
        var lastName: String
        var companyId: String?
        var jobTitle: String?
        var phone: String?
        var email: String?
        var notes: String?
    }

    struct Equipment: Decodable {
        var id: String
        var name: String
        var category: String?
        var identifier: String?
        var serialNumber: String?
        var notes: String?
        var createdDayOffset: Int
        var actions: [Action]

        struct Action: Decodable {
            /// "issue" or "return"
            var kind: String
            var dayOffset: Int
            var projectId: String?
            /// "person", "company" or "text"
            var recipientKind: String?
            var recipientId: String?
            var recipientName: String?
            var location: String?
            var notes: String?
            /// "good" or "damaged" (returns only)
            var condition: String?
        }
    }

    struct Project: Decodable {
        var id: String
        var key: String
        var name: String
        var description: String
        var createdDayOffset: Int
        var contactLinks: [ContactLink]
        var drawingFolders: [Folder]
        var drawings: [Drawing]
        var areas: [Area]
        var issues: [Issue]
        var photoAlbums: [Album]
        var photos: [Photo]
        var schedule: Schedule?
        var documentFolders: [Folder]
        var documents: [Document]
        var notes: [Note]
    }

    struct ContactLink: Decodable {
        var id: String
        /// "company" or "person"
        var kind: String
        var contactId: String
        var role: String?
    }

    struct Folder: Decodable { var id: String; var parentId: String?; var name: String; var sortOrder: Int }

    struct Drawing: Decodable {
        var id: String
        var folderId: String?
        var number: String
        var name: String
        var resource: String
        var pageCount: Int
        var pageWidth: Double
        var pageHeight: Double
        var revision: String?
        var discipline: String?
        var location: String?
        var drawingDate: String?
        var calibrations: [Calibration]
    }

    struct Calibration: Decodable {
        var id: String
        var pageIndex: Int
        var ax: Double
        var ay: Double
        var bx: Double
        var by: Double
        var enteredValue: Double
        var unit: String
    }

    struct Area: Decodable {
        var id: String
        var drawingId: String
        var pageIndex: Int
        var name: String
        var color: String
        var opacity: Double
        var vertices: [[Double]]
    }

    struct Issue: Decodable {
        var id: String
        var number: Int
        var drawingId: String
        var pageIndex: Int
        var x: Double
        var y: Double
        var areaId: String?
        var title: String
        var details: String
        var status: String
        var discipline: String?
        var contractor: String?
        var createdDayOffset: Int
        var createdMinute: Int
        var photos: [IssuePhoto]
    }

    struct IssuePhoto: Decodable { var id: String; var resource: String; var dayOffset: Int; var minute: Int }

    struct Album: Decodable { var id: String; var name: String; var sortOrder: Int }

    struct Photo: Decodable {
        var id: String
        var resource: String
        var albumId: String?
        var title: String
        var description: String
        var takenDayOffset: Int
        var takenMinute: Int
        var drawingId: String?
        var pageIndex: Int?
        var areaId: String?
        var issueId: String?
    }

    struct Schedule: Decodable {
        var id: String
        var name: String
        var details: String
        var phases: [Phase]
        var tasks: [TaskEntry]
        var dependencies: [Dependency]

        struct Phase: Decodable { var id: String; var name: String; var color: String; var sortOrder: Int }

        struct TaskEntry: Decodable {
            var id: String
            var phaseId: String?
            var kind: String
            var title: String
            var details: String
            var startOffset: Int
            var finishOffset: Int
            var progress: Int
            var status: String
            var responsibleName: String?
            var responsibleLinkId: String?
            var notes: String
            var sortOrder: Int
        }

        struct Dependency: Decodable { var id: String; var predecessorId: String; var successorId: String }
    }

    struct Document: Decodable {
        var id: String
        var folderId: String?
        var resource: String
        var originalFileName: String
        var name: String
        var category: String
        var description: String
        var revision: String?
        var revisionDate: String?
        var uploadedDayOffset: Int
    }

    struct Note: Decodable {
        var id: String
        var title: String
        var body: String
        var category: String?
        var createdDayOffset: Int
    }
}
#endif
